script:
(function () {
  'use strict';
  // What a second income adds to the household after taxes and the costs of working (yearly).
  //   Income-tax wages = gross - 401(k) deferral - health premiums (pre-tax)
  //   Federal / state tax = income-tax wages x the flat rates entered (the household's marginal rates)
  //   FICA wages = gross - health premiums (401(k) deferrals stay FICA-taxable)
  //   Social Security = 6.2% of FICA wages up to the wage base; Medicare = 1.45% (7.65% combined)
  //   Take-home = gross - 401(k) - premiums - taxes; net benefit = take-home - work costs x 12
  //   Effective hourly value = net benefit / (weeks x (work hours + commute hours per week))
  // Verified by hand and in a Node scratch test: $45,000 pay, 12% federal, 5% state -> federal
  //   $5,400, state $2,250, Social Security $2,790, Medicare $652.50, take-home $33,907.50; less
  //   $1,650/month of work costs ($19,800) = $14,107.50 a year, / 2,250 hours (50 weeks x 45 h) =
  //   $6.27 an hour. $200,000 pay, 10% 401(k), $3,000 premiums: Social Security capped at
  //   $11,439.00 ($184,500 x 6.2%), Medicare $2,856.50. Costs above take-home give a negative
  //   benefit with a plain message; blank or impossible inputs show an error instead of NaN.
  // ---- 2026 PAYROLL TAX CONSTANTS (tax year 2026) ----------------------------------------------
  // Social Security: 6.2% employee rate, 2026 wage base $184,500 (SSA 2026 COLA fact sheet).
  // Medicare: 1.45% employee rate (IRC 3101(b)). The 0.9% Additional Medicare Tax on wages above
  // $200,000 ($250,000 joint) is not modelled.
  var TAX_YEAR = 2026;
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500, MEDICARE_RATE = 0.0145;
  // -------------------------------------------------------------------------------------------
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function minus(v) { return v > 0 ? '-' + money0.format(v) : money0.format(0); }

  function update() {
    var ids = ['swPay', 'swHours', 'swWeeks', 'swCommuteHours', 'swFedRate', 'swStateRate', 'swChildcare',
               'swCommute', 'swMeals', 'swClothing', 'swOther', 'swRetire', 'swMatch', 'swPremiums'];
    var v = {};
    ids.forEach(function (id) { v[id] = num(id); });
    var error = document.getElementById('swError');
    var msg = '';
    if (ids.some(function (id) { return isNaN(v[id]); })) msg = 'Fill in every field with a number (use 0 where it does not apply).';
    else if (ids.some(function (id) { return v[id] < 0; })) msg = 'Values cannot be negative.';
    else if (v.swPay <= 0) msg = 'Enter the yearly pay before taxes.';
    else if (v.swHours <= 0 || v.swHours > 100) msg = 'Enter 1 to 100 work hours a week.';
    else if (v.swWeeks < 1 || v.swWeeks > 52) msg = 'Enter 1 to 52 weeks worked a year.';
    else if (v.swCommuteHours > 60) msg = 'Enter up to 60 commuting hours a week.';
    else if (v.swFedRate > 50 || v.swStateRate > 20) msg = 'Enter a federal rate up to 50% and a state rate up to 20%.';
    else if (v.swRetire > 100 || v.swMatch > 100) msg = 'Enter 401(k) percentages from 0 to 100%.';
    else if (v.swPay * v.swRetire / 100 + v.swPremiums > v.swPay) msg = '401(k) and health premiums cannot exceed the pay.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var gross = v.swPay;
    var retire = gross * v.swRetire / 100;
    var match = gross * v.swMatch / 100;
    var premiums = v.swPremiums;
    var incomeWages = gross - retire - premiums;
    var ficaWages = gross - premiums;
    var fed = incomeWages * v.swFedRate / 100;
    var state = incomeWages * v.swStateRate / 100;
    var ss = Math.min(ficaWages, SS_WAGE_BASE) * SS_RATE;
    var medicare = ficaWages * MEDICARE_RATE;
    var takeHome = gross - retire - premiums - fed - state - ss - medicare;
    var childcare = v.swChildcare * 12, commute = v.swCommute * 12,
        other = (v.swMeals + v.swClothing + v.swOther) * 12;
    var costs = childcare + commute + other;
    var net = takeHome - costs;
    var workHours = v.swWeeks * v.swHours;
    var allHours = v.swWeeks * (v.swHours + v.swCommuteHours);

    set('swNet', money0.format(net));
    set('swNetMonthly', money0.format(net / 12));
    set('swHourly', money.format(net / allHours));
    set('swGrossHourly', money.format(gross / workHours));
    set('swKept', Math.round(net / gross * 100) + '%');
    set('swGross', money0.format(gross));
    set('swRetireAmt', minus(retire));
    set('swPremiumsAmt', minus(premiums));
    set('swFed', minus(fed));
    set('swState', minus(state));
    set('swSs', minus(ss));
    set('swMedicare', minus(medicare));
    set('swTakeHome', money0.format(takeHome));
    set('swChildcareAmt', minus(childcare));
    set('swCommuteAmt', minus(commute));
    set('swOtherAmt', minus(other));
    set('swNet2', money0.format(net));
    set('swSaved', money0.format(retire + match));
    set('swTotal', money0.format(net + retire + match));
    set('swYear', String(TAX_YEAR));
    set('swVerdict', net <= 0
      ? 'After taxes and work costs this job would cost the household ' + money0.format(-net) + ' a year.'
      : 'The job adds ' + money0.format(net) + ' a year, or ' + money.format(net / allHours) +
        ' for each hour spent working and commuting.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('swForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
